# frozen_string_literal: true

# Attribute mapping of the puppetlabs-netscaler types onto NITRO. It was
# derived once from the puppetlabs-netscaler 1.x sources and is maintained by
# hand; run `rake generate:compat` after a change to refresh the
# lib/puppet/type/netscaler_*.rb files. `autorequire` maps a NITRO resource
# to the compat attribute (Symbol) or title part (String) naming it; both its
# netscaler_* and nitro_* types are autorequired. Special cases live in the
# lib/puppet/provider/netscaler_* providers.
module PuppetX
  module Netscaler
    COMPAT = {
      'netscaler_server' => {
        nitro: 'server',
        doc: "Manage basic netscaler server objects. The NetScaler appliance supports two types of servers: IP address based servers and domain based servers.",
        attributes: {
          address: { api: 'ipaddress', kind: :string, desc: "The domain name, IPv4 address, or IPv6 address of the server. When creating an IP address-based server, you can specify the name of the server instead of its IP address, when creating a service." },
          traffic_domain_id: { api: 'td', kind: :integer, init_only: true, desc: "Integer value that uniquely identifies the traffic domain in which you want to configure the entity." },
          comments: { api: 'comment', kind: :string, desc: "Any information about the server." },
          state: { api: 'state', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The state of the server." },
          disable_wait_time: { api: 'delay', kind: :integer, param: true, desc: "Specifies a wait time when disabling a server object. The server object continues to handle established connections for the specified amount of time, but rejects new connections" },
          graceful_shutdown: { api: 'graceful', kind: :truthy, values: ["YES", "NO"], param: true, desc: "Indicates graceful shutdown of the server. System will wait for all outstanding connections to this server to be closed before disabling the server." },
          translation_ip_address: { api: 'translationip', kind: :string, desc: "IP address used to transform the server's DNS-resolved IP address." },
          translation_mask: { api: 'translationmask', kind: :string, desc: "The netmask of the translation ip" },
          resolve_retry: { api: 'domainresolveretry', kind: :integer, desc: "Time, in seconds, for which the NetScaler appliance must wait, after DNS resolution fails, before sending the next DNS query to resolve the domain name.\nDefault = 5\nMin = 5\nMax = 20939" },
          ipv6_domain: { api: 'ipv6address', kind: :truthy, values: ["YES", "NO"], init_only: true, desc: "Support IPv6 addressing mode. If you configure a server with the IPv6 addressing mode, you cannot use the server in the IPv4 addressing mode" },
        },
      },
      'netscaler_service' => {
        nitro: 'service',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'server' => :server_name },
        doc: "Manage service on the NetScaler appliance. If the service is domain based, before you create the service, create the server entry by using the add server command. Then, in this command, specify the Server parameter.",
        attributes: {
          protocol: { api: 'servicetype', kind: :upcase, init_only: true, desc: "Protocol in which data is exchanged with the service. Required." },
          state: { api: 'state', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The state of the object." },
          server_name: { api: 'servername', kind: :string, init_only: true, desc: "Name of the server that hosts the service. Required." },
          port: { api: 'port', kind: :integer, init_only: true, desc: "Port number of the service. Required." },
          graceful_shutdown: { api: 'graceful', kind: :truthy, values: ["YES", "NO"], param: true, desc: "Indicates graceful shutdown of the server. System will wait for all outstanding connections to this server to be closed before disabling the server." },
          traffic_domain_id: { api: 'td', kind: :integer, init_only: true, desc: "Integer value that uniquely identifies the traffic domain in which you want to configure the entity." },
          hash_id: { api: 'hashid', kind: :integer, desc: "A numerical identifier that can be used by hash based load balancing methods. Must be unique for each service.\nMinimum value: 1" },
          server_id: { api: 'customserverid', kind: :string, desc: "Unique identifier for the service. Used when the persistency type for the virtual server is set to Custom Server ID." },
          clear_text_port: { api: 'cleartextport', kind: :integer, init_only: true, desc: "Port to which clear text data must be sent after the appliance decrypts incoming SSL traffic. Applicable to transparent SSL services." },
          cache_type: { api: 'cachetype', kind: :upcase, init_only: true, desc: "Cache type supported by the cache server." },
          cacheable: { api: 'cacheable', kind: :truthy, values: ["YES", "NO"], desc: "Use the transparent cache redirection virtual server to forward requests to the cache server. May not be specified if cache_type is 'TRANSPARENT', 'REVERSE', or 'FORWARD'" },
          health_monitoring: { api: 'healthmonitor', kind: :truthy, values: ["YES", "NO"], desc: "Monitor the health of this service. Available settings function as follows:\nYES - Send probes to check the health of the service.\nNO - Do not send probes to check the health of the service. With the NO option, the appliance shows the service as UP at all times." },
          appflow_logging: { api: 'appflowlog', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Enable logging of AppFlow information." },
          comments: { api: 'comment', kind: :string, desc: "Any information about the object." },
          max_clients: { api: 'maxclient', kind: :integer, desc: "Maximum number of simultaneous open connections to the service.\nMax = 4294967294" },
          max_requests: { api: 'maxreq', kind: :integer, desc: "Maximum number of requests that can be sent on a persistent connection to the service.\nNote: Connection requests beyond this value are rejected.\nMax = 65535" },
          max_bandwidth: { api: 'maxbandwidth', kind: :integer, desc: "Maximum bandwidth, in Kbps, allocated to the service.\nMax = 4294967287" },
          monitor_threshold: { api: 'monthreshold', kind: :integer, desc: "Minimum sum of weights of the monitors that are bound to this service. Used to determine whether to mark a service as UP or DOWN.\nMax = 65535" },
          client_idle_timeout: { api: 'clttimeout', kind: :integer, desc: "Time, in seconds, after which to terminate an idle client connection.\nMax = 31536000" },
          server_idle_timeout: { api: 'svrtimeout', kind: :integer, desc: "Time, in seconds, after which to terminate an idle server connection.\nMax = 31536000" },
          sure_connect: { kind: :truthy, values: ["ON", "OFF"], ignored: "SureConnect was removed from NetScaler firmware", desc: "State of SureConnect for the service." },
          surge_protection: { api: 'sp', kind: :truthy, values: ["ON", "OFF"], desc: "Enable surge protection for the service." },
          use_proxy_port: { api: 'useproxyport', kind: :truthy, values: ["YES", "NO"], desc: "Use the proxy port as the source port when initiating connections with the server. With the NO setting, the client-side connection port is used as the source port for the server-side connection.\nNote: This parameter is available only when the Use Source IP (USIP) parameter is set to YES." },
          down_state_flush: { api: 'downstateflush', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Flush all active transactions associated with a service whose state transitions from UP to DOWN. Do not enable this option for applications that must complete their transactions." },
          access_down: { api: 'accessdown', kind: :truthy, values: ["YES", "NO"], desc: "Use Layer 2 mode to bridge the packets sent to this service if it is marked as DOWN. If the service is DOWN, and this parameter is disabled, the packets are dropped." },
          use_source_ip: { api: 'usip', kind: :truthy, values: ["YES", "NO"], desc: "Use the client's IP address as the source IP address when initiating a connection to the server. When creating a service, if you do not set this parameter, the service inherits the global Use Source IP setting (available in the enable ns mode and disable ns mode CLI commands, or in the System > Settings > Configure modes > Configure Modes dialog box). However, you can override this setting after you create the service." },
          use_compression: { api: 'cmp', kind: :truthy, values: ["YES", "NO"], desc: "Enable compression for the service." },
          client_keepalive: { api: 'cka', kind: :truthy, values: ["YES", "NO"], desc: "Enable client keep-alive for the service." },
          tcp_buffering: { api: 'tcpb', kind: :truthy, values: ["YES", "NO"], desc: "Enable TCP buffering for the service." },
          client_ip: { api: 'cip', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Before forwarding a request to the service, insert an HTTP header with the client's IPv4 or IPv6 address as its value. Used if the server needs the client's IP address for security, accounting, or other purposes, and setting the Use Source IP parameter is not a viable option." },
          client_ip_header: { api: 'cipheader', kind: :string, desc: "Name for the HTTP header whose value must be set to the IP address of the client. Used with the Client IP parameter. If you set the Client IP parameter, and you do not specify a name for the header, the appliance uses the header name specified for the global Client IP Header parameter (the cipHeader parameter in the set ns param CLI command or the Client IP Header parameter in the Configure HTTP Parameters dialog box at System > Settings > Change HTTP parameters). If the global Client IP Header parameter is not specified, the appliance inserts a header with the name \\\"client-ip.\\\"" },
          net_profile_name: { api: 'netprofile', kind: :string, desc: "Network profile to use for the service." },
        },
      },
      'netscaler_servicegroup' => {
