          appflow_logging: { api: 'appflowlog', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Enable logging of AppFlow information." },
          comments: { api: 'comment', kind: :string, desc: "Any information about the object." },
          maximum_bandwidth: { api: 'maxbandwidth', kind: :integer, desc: "Maximum bandwidth, in Kbps, allocated to the service.\nMax = 4294967287" },
          monitor_threshold: { api: 'monthreshold', kind: :integer, desc: "Minimum sum of weights of the monitors that are bound to this service. Used to determine whether to mark a service as UP or DOWN.\nMax = 65535" },
          max_requests: { api: 'maxreq', kind: :integer, desc: "Maximum number of requests that can be sent on a persistent connection to the service.\nNote: Connection requests beyond this value are rejected.\nMax = 65535" },
          max_clients: { api: 'maxclient', kind: :integer, desc: "Maximum number of simultaneous open connections to the service.\nMax = 4294967294" },
          client_idle_timeout: { api: 'clttimeout', kind: :integer, desc: "Time, in seconds, after which to terminate an idle client connection.\nMax = 31536000" },
          server_idle_timeout: { api: 'svrtimeout', kind: :integer, desc: "Time, in seconds, after which to terminate an idle server connection.\nMax = 31536000" },
          sure_connect: { kind: :truthy, values: ["ON", "OFF"], ignored: "SureConnect was removed from NetScaler firmware", desc: "State of SureConnect for the service." },
          surge_protection: { api: 'sp', kind: :truthy, values: ["ON", "OFF"], desc: "Enable surge protection for the service." },
          use_proxy_port: { api: 'useproxyport', kind: :truthy, values: ["YES", "NO"], desc: "Use the proxy port as the source port when initiating connections with the server. With the NO setting, the client-side connection port is used as the source port for the server-side connection.\nNote: This parameter is available only when the Use Source IP (USIP) parameter is set to YES." },
          down_state_flush: { api: 'downstateflush', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Flush all active transactions associated with a service whose state transitions from UP to DOWN. Do not enable this option for applications that must complete their transactions." },
          use_client_ip: { api: 'usip', kind: :truthy, values: ["YES", "NO"], desc: "Use the client's IP address as the source IP address when initiating a connection to the server. When creating a service, if you do not set this parameter, the service inherits the global Use Source IP setting (available in the enable ns mode and disable ns mode CLI commands, or in the System > Settings > Configure modes > Configure Modes dialog box). However, you can override this setting after you create the service." },
          client_keepalive: { api: 'cka', kind: :truthy, values: ["YES", "NO"], desc: "Enable client keep-alive for the service." },
          tcp_buffering: { api: 'tcpb', kind: :truthy, values: ["YES", "NO"], desc: "Enable TCP buffering for the service." },
          http_compression: { kind: :truthy, values: ["ENABLED", "DISABLED"], ignored: "not supported by NITRO anymore", desc: "Enable compression for the specified service." },
          client_ip: { api: 'cip', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Before forwarding a request to the service, insert an HTTP header with the client's IPv4 or IPv6 address as its value. Used if the server needs the client's IP address for security, accounting, or other purposes, and setting the Use Source IP parameter is not a viable option." },
          client_ip_header: { api: 'cipheader', kind: :string, desc: "Name for the HTTP header whose value must be set to the IP address of the client. Used with the Client IP parameter. If you set the Client IP parameter, and you do not specify a name for the header, the appliance uses the header name specified for the global Client IP Header parameter (the cipHeader parameter in the set ns param CLI command or the Client IP Header parameter in the Configure HTTP Parameters dialog box at System > Settings > Change HTTP parameters). If the global Client IP Header parameter is not specified, the appliance inserts a header with the name \\\"client-ip.\\\"" },
          tcp_profile: { api: 'tcpprofilename', kind: :string, desc: "Name of the TCP profile that contains TCP configuration settings for the service group." },
          http_profile: { api: 'httpprofilename', kind: :string, desc: "Name of the HTTP profile that contains HTTP configuration settings for the service group." },
