      'netscaler_servicegroup_member' => {
        nitro: 'servicegroup_servicegroupmember_binding',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'servicegroup' => 'servicegroupname', 'server' => 'servername' },
        doc: "Manage a member of a servicegroup.",
        title_format: '%{servicegroupname}/%{servername}:%{port}',
        title_pattern: %r{\A(?<servicegroupname>[^/]+)/(?<servername>.+):(?<port>\d+)\z},
        attributes: {
          weight: { api: 'weight', kind: :integer, desc: "Weight to assign to the servers in the service group. Specifies the capacity of the servers relative to the other servers in the load balancing configuration. The higher the weight, the higher the percentage of requests sent to the service.\nMin = 1\nMax = 100" },
          state: { api: 'state', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The configured state (enable/disable) of the service group." },
        },
      },
      'netscaler_lbvserver' => {
        nitro: 'lbvserver',
        doc: "Manage Load Balanced VServer on the NetScaler appliance.",
        attributes: {
          service_type: { api: 'servicetype', kind: :upcase, init_only: true, desc: "Protocol used by the service (also called the service type). Valid options: HTTP, FTP, TCP, UDP, SSL, SSL_BRIDGE, SSL_TCP, DTLS, NNTP, DNS, DHCPRA, ANY, SIP_UDP, DNS_TCP, RTSP, PUSH, SSL_PUSH, RADIUS, RDP, MYSQL, MSSQL, DIAMETER, SSL_DIAMETER, TFTP, ORACLE." },
          ip_address: { api: 'ipv46', kind: :string, desc: "IPv4 or IPv6 address to assign to the virtual server." },
          ip_pattern: { api: 'ippattern', kind: :string, desc: "IP address pattern, in dotted decimal notation, for identifying packets to be accepted by the virtual server. The IP Mask parameter specifies which part of the destination IP address is matched against the pattern. Mutually exclusive with the IP Address parameter.\nFor example, if the IP pattern assigned to the virtual server is 198.51.100.0 and the IP mask is 255.255.240.0 (a forward mask), the first 20 bits in the destination IP addresses are matched with the first 20 bits in the pattern. The virtual server accepts requests with IP addresses that range from 198.51.96.1 to 198.51.111.254. You can also use a pattern such as 0.0.2.2 and a mask such as 0.0.255.255 (a reverse mask).\nIf a destination IP address matches more than one IP pattern, the pattern with the longest match is selected, and the associated virtual server processes the request. For example, if virtual servers vs1 and vs2 have the same IP pattern, 0.0.100.128, but different IP masks of 0.0.255.255 and 0.0.224.255, a destination IP address of 198.51.100.128 has the longest match with the IP pattern of vs1. If a destination IP address matches two or more virtual servers to the same extent, the request is processed by the virtual server whose port number matches the port number in the request." },
          ip_mask: { api: 'ipmask', kind: :string, desc: "IP mask, in dotted decimal notation, for the IP Pattern parameter. Can have leading or trailing non-zero octets (for example, 255.255.240.0 or 0.0.255.255). Accordingly, the mask specifies whether the first n bits or the last n bits of the destination IP address in a client request are to be matched with the corresponding bits in the IP pattern. The former is called a forward mask. The latter is called a reverse mask." },
          port: { api: 'port', kind: :integer, init_only: true, desc: "Port number for the virtual server." },
          range: { api: 'range', kind: :integer, init_only: true, desc: "Number of IP addresses that the appliance must generate and assign to the virtual server. The virtual server then functions as a network virtual server, accepting traffic on any of the generated IP addresses. The IP addresses are generated automatically, as follows:\n* For a range of n, the last octet of the address specified by the IP Address parameter increments n-1 times.\n* If the last octet exceeds 255, it rolls over to 0 and the third octet increments by 1.\nNote: The Range parameter assigns multiple IP addresses to one virtual server. To generate an array of virtual servers, each of which owns only one IP address, use brackets in the IP Address and Name parameters to specify the range. For example:\nadd lb vserver my_vserver[1-3] HTTP 192.0.2.[1-3] 80\nMinimum value: 1\nMaximum value: 254" },
          persistence_type: { api: 'persistencetype', kind: :upcase, desc: "Type of persistence for the virtual server. Available settings function as follows:\n* SOURCEIP - Connections from the same client IP address belong to the same persistence session.\n* COOKIEINSERT - Connections that have the same HTTP Cookie, inserted by a Set-Cookie directive from a server, belong to the same persistence session.\n* SSLSESSION - Connections that have the same SSL Session ID belong to the same persistence session.\n* CUSTOMSERVERID - Connections with the same server ID form part of the same session. For this persistence type, set the Server ID (CustomServerID) parameter for each service and configure the Rule parameter to identify the server ID in a request.\n* RULE - All connections that match a user defined rule belong to the same persistence session.\n* URLPASSIVE - Requests that have the same server ID in the URL query belong to the same persistence session. The server ID is the hexadecimal representation of the IP address and port of the service to which the request must be forwarded. This persistence type requires a rule to identify the server ID in the request.\n* DESTIP - Connections to the same destination IP address belong to the same persistence session.\n* SRCIPDESTIP - Connections that have the same source IP address and destination IP address belong to the same persistence session.\n* CALLID - Connections that have the same CALL-ID SIP header belong to the same persistence session.\n* RTSPSID - Connections that have the same RTSP Session ID belong to the same persistence session." },
          persistence_timeout: { api: 'timeout', kind: :integer, desc: "Time period for which a persistence session is in effect.\nMaximum value: 1440" },
          persistence_backup: { api: 'persistencebackup', kind: :upcase, desc: "Backup persistence type for the virtual server. Becomes operational if the primary persistence mechanism fails. Valid options: SOURCEIP, NONE." },
          backup_persistence_timeout: { api: 'backuppersistencetimeout', kind: :integer, desc: "Time period for which backup persistence is in effect.\nMinimum value: 2\nMaximum value: 1440" },
          lb_method: { api: 'lbmethod', kind: :upcase, desc: "Load balancing method. The available settings function as follows:\n* ROUNDROBIN - Distribute requests in rotation, regardless of the load. Weights can be assigned to services to enforce weighted round robin distribution.\n* LEASTCONNECTION (default) - Select the service with the fewest connections.\n* LEASTRESPONSETIME - Select the service with the lowest average response time.\n* LEASTBANDWIDTH - Select the service currently handling the least traffic.\n* LEASTPACKETS - Select the service currently serving the lowest number of packets per second.\n* CUSTOMLOAD - Base service selection on the SNMP metrics obtained by custom load monitors.\n* LRTM - Select the service with the lowest response time. Response times are learned through monitoring probes. This method also takes the number of active connections into account.\nAlso available are a number of hashing methods, in which the appliance extracts a predetermined portion of the request, creates a hash of the portion, and then checks whether any previous requests had the same hash value. If it finds a match, it forwards the request to the service that served those previous requests. Following are the hashing methods:\n* URLHASH - Create a hash of the request URL (or part of the URL).\n* DOMAINHASH - Create a hash of the domain name in the request (or part of the domain name). The domain name is taken from either the URL or the Host header. If the domain name appears in both locations, the URL is preferred. If the request does not contain a domain name, the load balancing method defaults to LEASTCONNECTION.\n* DESTINATIONIPHASH - Create a hash of the destination IP address in the IP header.\n* SOURCEIPHASH - Create a hash of the source IP address in the IP header.\n* TOKEN - Extract a token from the request, create a hash of the token, and then select the service to which any previous requests with the same token hash value were sent.\n* SRCIPDESTIPHASH - Create a hash of the string obtained by concatenating the source IP address and destination IP address in the IP header.\n* SRCIPSRCPORTHASH - Create a hash of the source IP address and source port in the IP header.\n* CALLIDHASH - Create a hash of the SIP Call-ID header." },
          lb_method_hash_length: { api: 'hashlength', kind: :integer, desc: "Number of bytes to consider for the hash value used in the URLHASH and DOMAINHASH load balancing methods.\nMinimum value = 1\nMaximum value = 4096" },
          lb_method_netmask: { api: 'netmask', kind: :string, desc: "IPv4 subnet mask to apply to the destination IP address or source IP address when the load balancing method is DESTINATIONIPHASH or SOURCEIPHASH.\nMinimum length = 1" },
          lb_method_ipv6_mask_length: { api: 'v6netmasklen', kind: :integer, desc: "Number of bits to consider in an IPv6 destination or source IP address, for creating the hash that is required by the DESTINATIONIPHASH and SOURCEIPHASH load balancing methods.\nMinimum value = 1\nMaximum value = 128" },
          cookie_name: { api: 'cookiename', kind: :string, desc: "Use this parameter to specify the cookie name for COOKIE peristence type. It specifies the name of cookie with a maximum of 32 characters. If not specified, cookie name is internally generated." },
          rule: { api: 'rule', kind: :string, desc: "Expression, or name of a named expression, against which traffic is evaluated. Written in the classic or default syntax.\nNote:\nMaximum length of a string literal in the expression is 255 characters. A longer string can be split into smaller strings of up to 255 characters each, and the smaller strings concatenated with the + operator. For example, you can create a 500-character string as follows: '\\\"<string of 255 characters>\\\" \\+ \\\"<string of 245 characters>\\\"'\nThe following requirements apply only to the NetScaler CLI:\n* If the expression includes one or more spaces, enclose the entire expression in double quotation marks.\n* If the expression itself includes double quotation marks, escape the quotations by using the \\ character.\n* Alternatively, you can use single quotation marks to enclose the rule, in which case you do not have to escape the double quotation marks." },
          listen_policy: { api: 'listenpolicy', kind: :string, desc: "Default syntax expression identifying traffic accepted by the virtual server. Can be either an expression (for example, CLIENT.IP.DST.IN_SUBNET(192.0.2.0/24) or the name of a named expression. In the above example, the virtual server accepts all requests whose destination IP address is in the 192.0.2.0/24 subnet." },
          listen_priority: { api: 'listenpriority', kind: :integer, desc: "Integer specifying the priority of the listen policy. A higher number specifies a lower priority. If a request matches the listen policies of more than one virtual server the virtual server whose listen policy has the highest priority (the lowest priority number) accepts the request.\nMaximum value: 101" },
          response_rule: { api: 'resrule', kind: :string, desc: "Default syntax expression specifying which part of a server's response to use for creating rule based persistence sessions (persistence type RULE). Can be either an expression or the name of a named expression.\nExample:\nHTTP.RES.HEADER(\\\"setcookie\\\").VALUE(0).TYPECAST_NVLIST_T('=',';').VALUE(\\\"server1\\\")." },
          persistence_ipv4_mask: { api: 'persistmask', kind: :string, desc: "Persistence mask for IP based persistence types, for IPv4 virtual servers." },
          persistence_ipv6_mask_length: { api: 'v6persistmasklen', kind: :integer, desc: "Persistence mask for IP based persistence types, for IPv6 virtual servers.\nMinimum value: 1\nMaximum value: 128" },
          priority_queuing: { kind: :truthy, values: ["ON", "OFF"], ignored: "priority queuing was removed from NetScaler firmware", desc: "Use priority queuing on the virtual server. based persistence types, for IPv6 virtual servers." },
          sure_connect: { kind: :truthy, values: ["ON", "OFF"], ignored: "SureConnect was removed from NetScaler firmware", desc: "Use SureConnect on the virtual server." },
          rtsp_natting: { api: 'rtspnat', kind: :truthy, values: ["ON", "OFF"], desc: "Use network address translation (NAT) for RTSP data connections." },
          redirection_mode: { api: 'm', kind: :upcase, desc: "Redirection mode for load balancing. Available settings function as follows:\n* IP - Before forwarding a request to a server, change the destination IP address to the server's IP address.\n* MAC - Before forwarding a request to a server, change the destination MAC address to the server's MAC address. The destination IP address is not changed. MAC-based redirection mode is used mostly in firewall load balancing deployments.\n* IPTUNNEL - Perform IP-in-IP encapsulation for client IP packets. In the outer IP headers, set the destination IP address to the IP address of the server and the source IP address to the subnet IP (SNIP). The client IP packets are not modified. Applicable to both IPv4 and IPv6 packets.\n* TOS - Encode the virtual server's TOS ID in the TOS field of the IP header.\nYou can use either the IPTUNNEL or the TOS option to implement Direct Server Return (DSR)." },
          tos_id: { api: 'tosid', kind: :integer, desc: "TOS ID of the virtual server. Applicable only when the load balancing redirection mode is set to TOS.\nMinimum value: 1\nMaximum value: 63" },
          data_length: { api: 'datalength', kind: :integer, desc: "Length of the token to be extracted from the data segment of an incoming packet, for use in the token method of load balancing. The length of the token, specified in bytes, must not be greater than 24 KB. Applicable to virtual servers of type TCP.\nMinimum value: 1\nMaximum value: 100" },
          data_offset: { api: 'dataoffset', kind: :integer, desc: "Offset to be considered when extracting a token from the TCP payload. Applicable to virtual servers, of type TCP, using the token method of load balancing. Must be within the first 24 KB of the TCP payload.\nMaximum value: 25400" },
          sessionless: { api: 'sessionless', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Perform load balancing on a per-packet basis, without establishing sessions. Recommended for load balancing of intrusion detection system (IDS) servers and scenarios involving direct server return (DSR), where session information is unnecessary." },
          state: { api: 'state', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "State of the load balancing virtual server." },
          connection_failover: { api: 'connfailover', kind: :upcase, desc: "Mode in which the connection failover feature must operate for the virtual server. After a failover, established TCP connections and UDP packet flows are kept active and resumed on the secondary appliance. Clients remain connected to the same servers. Available settings function as follows:\n* STATEFUL - The primary appliance shares state information with the secondary appliance, in real time, resulting in some runtime processing overhead.\n* STATELESS - State information is not shared, and the new primary appliance tries to re-create the packet flow on the basis of the information contained in the packets it receives.\n* DISABLED - Connection failover does not occur." },
          redirect_url: { api: 'redirurl', kind: :string, desc: "URL to which to redirect traffic if the virtual server becomes unavailable.\nWARNING! Make sure that the domain in the URL does not match the domain specified for a content switching policy. If it does, requests are continuously redirected to the unavailable virtual server." },
          cacheable: { api: 'cacheable', kind: :truthy, values: ["YES", "NO"], desc: "Route cacheable requests to a cache redirection virtual server. The load balancing virtual server can forward requests only to a transparent cache redirection virtual server that has an IP address and port combination of *:80, so such a cache redirection virtual server must be configured on the appliance." },
          client_timeout: { api: 'clttimeout', kind: :integer, desc: "Idle time, in seconds, after which a client connection is terminated.\nMaximum value: 31536000" },
          spillover_method: { api: 'somethod', kind: :upcase, desc: "Type of threshold that, when exceeded, triggers spillover. Available settings function as follows:\n* CONNECTION - Spillover occurs when the number of client connections exceeds the threshold.\n* DYNAMICCONNECTION - Spillover occurs when the number of client connections at the virtual server exceeds the sum of the maximum client (Max Clients) settings for bound services. Do not specify a spillover threshold for this setting, because the threshold is implied by the Max Clients settings of bound services.\n* BANDWIDTH - Spillover occurs when the bandwidth consumed by the virtual server's incoming and outgoing traffic exceeds the threshold.\n* HEALTH - Spillover occurs when the percentage of weights of the services that are UP drops below the threshold. For example, if services svc1, svc2, and svc3 are bound to a virtual server, with weights 1, 2, and 3, and the spillover threshold is 50%, spillover occurs if svc1 and svc3 or svc2 and svc3 transition to DOWN.\n* NONE - Spillover does not occur." },
          spillover_persistence: { api: 'sopersistence', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "If spillover occurs, maintain source IP address based persistence for both primary and backup virtual servers." },
          spillover_persistence_timeout: { api: 'sopersistencetimeout', kind: :integer, desc: "Timeout for spillover persistence, in minutes.\nMinimum value: 2\nMaximum value: 1440" },
          health_threshold: { api: 'healththreshold', kind: :integer, desc: "Threshold in percent of active services below which vserver state is made down. If this threshold is 0, vserver state will be up even if one bound service is up.\nMinimum value: 0\nMaximum value: 100" },
          spillover_threshold: { api: 'sothreshold', kind: :integer, desc: "Threshold at which spillover occurs. Specify an integer for the CONNECTION spillover method, a bandwidth value in kilobits per second for the BANDWIDTH method (do not enter the units), or a percentage for the HEALTH method (do not enter the percentage symbol).\nMinimum value: 1\nMaximum value: 4294967287" },
          spillover_backup_action: { api: 'sobackupaction', kind: :upcase, desc: "Action to be performed if spillover is to take effect, but no backup chain to spillover is usable or exists. Valid options: DROP, ACCEPT, REDIRECT." },
          redirect_port_rewrite: { api: 'redirectportrewrite', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Rewrite the port and change the protocol to ensure successful HTTP redirects from services." },
          down_state_flush: { api: 'downstateflush', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Flush all active transactions associated with a virtual server whose state transitions from UP to DOWN. Do not enable this option for applications that must complete their transactions." },
          backup_virtual_server: { api: 'backupvserver', kind: :string, desc: "Name of the backup virtual server to which to forward requests if the primary virtual server goes DOWN or reaches its spillover threshold." },
          disable_primary_on_down: { api: 'disableprimaryondown', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "If the primary virtual server goes down, do not allow it to return to primary status until manually enabled." },
          virtual_server_ip_port_insertion: { api: 'insertvserveripport', kind: :upcase, desc: "Insert an HTTP header, whose value is the IP address and port number of the virtual server, before forwarding a request to the server. The format of the header is <vipHeader>: <virtual server IP address>_<port number >, where vipHeader is the name that you specify for the header. If the virtual server has an IPv6 address, the address in the header is enclosed in brackets ([ and ]) to separate it from the port number. If you have mapped an IPv4 address to a virtual server's IPv6 address, the value of this parameter determines which IP address is inserted in the header, as follows:\n* VIPADDR - Insert the IP address of the virtual server in the HTTP header regardless of whether the virtual server has an IPv4 address or an IPv6 address. A mapped IPv4 address, if configured, is ignored.\n* V6TOV4MAPPING - Insert the IPv4 address that is mapped to the virtual server's IPv6 address. If a mapped IPv4 address is not configured, insert the IPv6 address.\n* OFF - Disable header insertion." },
          vip_header_name: { api: 'vipheader', kind: :string, desc: "Name for the inserted header. The default name is vip-header." },
          authentication_fqdn: { api: 'authenticationhost', kind: :string, desc: "Fully qualified domain name (FQDN) of the authentication virtual server to which the user must be redirected for authentication. Make sure that the Authentication parameter is set to ENABLED." },
          authentication: { api: 'authentication', kind: :truthy, values: ["ON", "OFF"], desc: "Enable or disable user authentication." },
          authentication_401: { api: 'authn401', kind: :truthy, values: ["ON", "OFF"], desc: "Enable or disable user authentication with HTTP 401 responses." },
          authentication_virtual_server_name: { api: 'authnvsname', kind: :string, desc: "Name of an authentication virtual server with which to authenticate users." },
          push: { api: 'push', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Process traffic with the push virtual server that is bound to this load balancing virtual server." },
          push_virtual_server_name: { api: 'pushvserver', kind: :string, desc: "Name of the load balancing virtual server, of type PUSH or SSL_PUSH, to which the server pushes updates received on the load balancing virtual server that you are configuring." },
          push_label_expression: { api: 'pushlabel', kind: :string, desc: "Expression for extracting a label from the server's response. Can be either an expression or the name of a named expression." },
          push_multiple_clients: { api: 'pushmulticlients', kind: :truthy, values: ["YES", "NO"], desc: "Allow multiple Web 2.0 connections from the same client to connect to the virtual server and expect updates." },
          tcp_profile_name: { api: 'tcpprofilename', kind: :string, desc: "Name of the TCP profile whose settings are to be applied to the virtual server." },
          http_profile_name: { api: 'httpprofilename', kind: :string, desc: "Name of the HTTP profile whose settings are to be applied to the virtual server." },
          db_profile_name: { api: 'dbprofilename', kind: :string, desc: "Name of the DB profile whose settings are to be applied to the virtual server." },
          comment: { api: 'comment', kind: :string, desc: "Any comments that you might want to associate with the virtual server." },
          layer2_parameters: { api: 'l2conn', kind: :truthy, values: ["ON", "OFF"], desc: "Use Layer 2 parameters (channel number, MAC address, and VLAN ID) in addition to the 4-tuple (<source IP>:<source port>::<destination IP>:<destination port>) that is used to identify a connection. Allows multiple TCP and non-TCP connections with the same 4-tuple to co-exist on the NetScaler appliance." },
          oracle_server_version: { api: 'oracleserverversion', kind: :upcase, desc: "Oracle server version. Valid options: 10G, 11G." },
          mssql_server_version: { api: 'mssqlserverversion', kind: :upcase, desc: "For a load balancing virtual server of type MSSQL, the Microsoft SQL Server version. Set this parameter if you expect some clients to run a version different from the version of the database. This setting provides compatibility between the client-side and server-side connections by ensuring that all communication conforms to the server's version. Valid options: 70, 2000, 2000SP1, 2005, 2008, 2008R2, 2012." },
          mysql_protocol_version: { api: 'mysqlprotocolversion', kind: :integer, desc: "MySQL protocol version that the virtual server advertises to clients." },
          mysql_server_version: { api: 'mysqlserverversion', kind: :string, desc: "MySQL server version string that the virtual server advertises to clients." },
          mysql_character_set: { api: 'mysqlcharacterset', kind: :integer, desc: "Character set that the virtual server advertises to clients." },
          mysql_server_capabilities: { api: 'mysqlservercapabilities', kind: :integer, desc: "Server capabilities that the virtual server advertises to clients." },
          appflow_logging: { api: 'appflowlog', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Apply AppFlow logging to the virtual server." },
          net_profile_name: { api: 'netprofile', kind: :string, desc: "Name of the network profile to associate with the virtual server. If you set this parameter, the virtual server uses only the IP addresses in the network profile as source IP addresses when initiating connections with servers." },
          icmp_virtual_server_response: { api: 'icmpvsrresponse', kind: :upcase, desc: "How the NetScaler appliance responds to ping requests received for an IP address that is common to one or more virtual servers. Available settings function as follows:\n* If set to PASSIVE on all the virtual servers that share the IP address, the appliance always responds to the ping requests.\n* If set to ACTIVE on all the virtual servers that share the IP address, the appliance responds to the ping requests if at least one of the virtual servers is UP. Otherwise, the appliance does not respond.\n* If set to ACTIVE on some virtual servers and PASSIVE on the others, the appliance responds if at least one virtual server with the ACTIVE setting is UP. Otherwise, the appliance does not respond.\nNote: This parameter is available at the virtual server level. A similar parameter, ICMP Response, is available at the IP address level, for IPv4 addresses of type VIP. To set that parameter, use the add ip command in the CLI or the Create IP dialog box in the GUI." },
          rhi_state: { api: 'rhistate', kind: :upcase, desc: "Route Health Injection (RHI) functionality of the NetSaler appliance for advertising the route of the VIP address associated with the virtual server. When Vserver RHI Level (RHI) parameter is set to VSVR_CNTRLD, the following are different RHI behaviors for the VIP address on the basis of RHIstate (RHI STATE) settings on the virtual servers associated with the VIP address:\n* If you set RHI STATE to PASSIVE on all virtual servers, the NetScaler ADC always advertises the route for the VIP address.\n* If you set RHI STATE to ACTIVE on all virtual servers, the NetScaler ADC advertises the route for the VIP address if at least one of the associated virtual servers is in UP state.\n* If you set RHI STATE to ACTIVE on some and PASSIVE on others, the NetScaler ADC advertises the route for the VIP address if at least one of the associated virtual servers, whose RHI STATE set to ACTIVE, is in UP state." },
          new_service_request_rate: { api: 'newservicerequest', kind: :integer, desc: "Number of requests, or percentage of the load on existing services, by which to increase the load on a new service at each interval in slow-start mode. A non-zero value indicates that slow-start is applicable. A zero value indicates that the global RR startup parameter is applied. Changing the value to zero will cause services currently in slow start to take the full traffic as determined by the LB method. Subsequently, any new services added will use the global RR factor." },
          new_service_request_unit: { api: 'newservicerequestunit', kind: :upcase, desc: "Units in which to increment load at each interval in slow-start mode.\nPossible values = PER_SECOND, PERCENT" },
          new_service_request_increment_interval: { api: 'newservicerequestincrementinterval', kind: :integer, desc: "Interval, in seconds, between successive increments in the load on a new service or a service whose state has just changed from DOWN to UP. A value of 0 (zero) specifies manual slow start.\nMaximum value: 3600" },
          min_autoscale_members: { api: 'minautoscalemembers', kind: :integer, desc: "Minimum number of members expected to be present when vserver is used in Autoscale.\nMaximum value: 5000" },
          max_autoscale_members: { api: 'maxautoscalemembers', kind: :integer, desc: "Maximum number of members expected to be present when vserver is used in Autoscale.\nMaximum value: 5000" },
          persist_avp_no: { api: 'persistavpno', kind: :array, desc: "Persist AVP number for Diameter Persistency.\nIn case this AVP is not defined in Base RFC 3588 and it is nested inside a Grouped AVP,\ndefine a sequence of AVP numbers (max 3) in order of parent to child. So say persist AVP number X\nis nested inside AVP Y which is nested in Z, then define the list as Z Y X\nMinimum value: 1" },
          # Not :upcase: NITRO spells the values in mixed case (Bypass, ReLb,
          # None) and returns them that way, so upcasing breaks strict mode;
          # puppetlabs-netscaler never upcased them either.
          skip_persistency: { api: 'skippersistency', kind: :string, desc: "This argument decides the behavior incase the service which is selected from an existing persistence session has reached threshold. Valid options: Bypass, ReLb, None." },
          traffic_domain: { api: 'td', kind: :integer, init_only: true, desc: "Integer value that uniquely identifies the traffic domain in which you want to configure the entity. If you do not specify an ID, the entity becomes part of the default traffic domain, which has an ID of 0.\nMinimum value: 0\nMaximum value: 4094" },
          authentication_profile_name: { api: 'authnprofile', kind: :string, desc: "Name of the authentication profile to be used when authentication is turned on." },
          macmode_retain_vlan: { api: 'macmoderetainvlan', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "This option is used to retain vlan information of incoming packet when macmode is enabled" },
          database_specific_lb: { api: 'dbslb', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Enable database specific load balancing for MySQL and MSSQL service types." },
          dns64: { api: 'dns64', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "This argument is for enabling/disabling the dns64 on lbvserver" },
          bypass_aaaa: { api: 'bypassaaaa', kind: :truthy, values: ["YES", "NO"], desc: "If this option is enabled while resolving DNS64 query AAAA queries are not sent to back end dns server" },
          recursion_available: { api: 'recursionavailable', kind: :truthy, values: ["YES", "NO"], desc: "When set to YES, this option causes the DNS replies from this vserver to have the RA bit turned on. Typically one would set this option to YES, when the vserver is load balancing a set of DNS servers thatsupport recursive queries." },
          process_local: { api: 'processlocal', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "By turning on this option packets destined to a vserver in a cluster will not under go any steering. Turn this option for single packet request response mode or when the upstream device is performing a proper RSS for connection based distribution." },
        },
      },
      'netscaler_lbvserver_service_binding' => {
        nitro: 'lbvserver_service_binding',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'lbvserver' => 'name', 'service' => 'servicename' },
        doc: "Manage a binding between a loadbalancing vserver and a service.",
        title_format: '%{name}/%{servicename}',
        title_pattern: %r{\A(?<name>[^/]+)/(?<servicename>.+)\z},
        attributes: {
          weight: { api: 'weight', kind: :integer, desc: "Weight to assign to the specified service.\nMin = 1\nMax = 100" },
        },
      },
      'netscaler_lbvserver_servicegroup_binding' => {
        nitro: 'lbvserver_servicegroup_binding',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'lbvserver' => 'name', 'servicegroup' => 'servicegroupname' },
        doc: "Manage a binding between a loadbalancing vserver and a servicegroup.",
        title_format: '%{name}/%{servicegroupname}',
        title_pattern: %r{\A(?<name>[^/]+)/(?<servicegroupname>.+)\z},
        attributes: {
        },
      },
      'netscaler_lbmonitor' => {
        nitro: 'lbmonitor',
        doc: "Manage service on the NetScaler appliance. If the service is domain based, before you create the service, create the server entry by using the add server command. Then, in this command, specify the Server parameter.",
        attributes: {
          type: { api: 'type', kind: :upcase, init_only: true, desc: "Type of monitor that you want to create.\nPossible values: PING, TCP, HTTP, TCP-ECV, HTTP-ECV, UDP-ECV, DNS, FTP, LDNS-PING, LDNS-TCP, LDNS-DNS, RADIUS, USER, HTTP-INLINE, SIP-UDP, LOAD, FTP-EXTENDED, SMTP, SNMP, NNTP, MYSQL, MYSQL-ECV, MSSQL-ECV, ORACLE-ECV, LDAP, POP3, CITRIX-XML-SERVICE, CITRIX-WEB-INTERFACE, DNS-TCP, RTSP, ARP, CITRIX-AG, CITRIX-AAC-LOGINPAGE, CITRIX-AAC-LAS, CITRIX-XD-DDC, ND6, CITRIX-WI-EXTENDED, DIAMETER, RADIUS_ACCOUNTING, STOREFRONT, APPC, CITRIX-XNC-ECV, CITRIX-XDM" },
          interval: { api: 'interval', kind: :integer, desc: "Time interval between two successive probes. Must be greater than the value of Response Time-out.\nDefault value: 5\nMinimum value: 1\nMaximum value: 20940000" },
          destination_ip: { api: 'destip', kind: :string, desc: "IP address of the service to which to send probes. If the parameter is set to 0, the IP address of the server to which the monitor is bound is considered the destination IP address." },
          response_timeout: { api: 'resptimeout', kind: :integer, desc: "Amount of time for which the appliance must wait before it marks a probe as FAILED. Must be less than the value specified for the Interval parameter.\nNote: For UDP-ECV monitors for which a receive string is not configured, response timeout does not apply. For UDP-ECV monitors with no receive string, probe failure is indicated by an ICMP port unreachable error received from the service.\nDefault value: 2\nMinimum value: 1\nMaximum value: 20939000" },
          destination_port: { api: 'destport', kind: :integer, desc: "TCP or UDP port to which to send the probe. If the parameter is set to 0, the port number of the service to which the monitor is bound is considered the destination port. For a monitor of type USER, however, the destination port is the port number that is included in the HTTP request sent to the dispatcher. Does not apply to monitors of type PING." },
          down_time: { api: 'downtime', kind: :integer, desc: "Time duration for which to wait before probing a service that has been marked as DOWN. Expressed in milliseconds, seconds, or minutes.\nDefault value: 30\nMinimum value: 1\nMaximum value: 20939000" },
          deviation: { api: 'deviation', kind: :integer, desc: "Time value added to the learned average response time in dynamic response time monitoring (DRTM). When a deviation is specified, the appliance learns the average response time of bound services and adds the deviation to the average. The final value is then continually adjusted to accommodate response time variations over time. Specified in milliseconds, seconds, or minutes.\nMaximum value: 20939000" },
          retries: { api: 'retries', kind: :integer, desc: "Maximum number of probes to send to establish the state of a service for which a monitoring probe failed.\nDefault value: 3\nMinimum value: 1\nMaximum value: 127" },
          resp_timeout_threshold: { api: 'resptimeoutthresh', kind: :integer, desc: "Response time threshold, specified as a percentage of the Response Time-out parameter. If the response to a monitor probe has not arrived when the threshold is reached, the appliance generates an SNMP trap called monRespTimeoutAboveThresh. After the response time returns to a value below the threshold, the appliance generates a monRespTimeoutBelowThresh SNMP trap. For the traps to be generated, the \"MONITOR-RTO-THRESHOLD\" alarm must also be enabled.\nMaximum value: 100" },
          snmp_alert_retries: { api: 'alertretries', kind: :integer, desc: "Number of consecutive probe failures after which the appliance generates an SNMP trap called monProbeFailed.\nMaximum value: 32" },
          action: { api: 'action', kind: :string, desc: "Action to perform when the response to an inline monitor (a monitor of type HTTP-INLINE) indicates that the service is down. A service monitored by an inline monitor is considered DOWN if the response code is not one of the codes that have been specified for the Response Code parameter.\nAvailable settings function as follows:\n* NONE - Do not take any action. However, the show service command and the show lb monitor command indicate the total number of responses that were checked and the number of consecutive error responses received after the last successful probe.\n* LOG - Log the event in NSLOG or SYSLOG.\n* DOWN - Mark the service as being down, and then do not direct any traffic to the service until the configured down time has expired. Persistent connections to the service are terminated as soon as the service is marked as DOWN. Also, log the event in NSLOG or SYSLOG.\nPossible values: NONE, LOG, DOWN\nDefault value: SM_DOWN" },
          success_retries: { api: 'successretries', kind: :integer, desc: "Number of consecutive successful probes required to transition a service's state from DOWN to UP.\nDefault value: 1\nMinimum value: 1\nMaximum value: 32" },
          failure_retries: { api: 'failureretries', kind: :integer, desc: "Number of retries that must fail, out of the number specified for the Retries parameter, for a service to be marked as DOWN. For example, if the Retries parameter is set to 10 and the Failure Retries parameter is set to 6, out of the ten probes sent, at least six probes must fail if the service is to be marked as DOWN. The default value of 0 means that all the retries must fail if the service is to be marked as DOWN.\nMaximum value: 32" },
          net_profile: { api: 'netprofile', kind: :string, desc: "Name of the network profile." },
          tos: { api: 'tos', kind: :truthy, values: ["YES", "NO"], desc: "Probe the service by encoding the destination IP address in the IP TOS (6) bits.\nPossible values: YES, NO" },
          tos_id: { api: 'tosid', kind: :integer, desc: "The TOS ID of the specified destination IP. Applicable only when the TOS parameter is set.\nMinimum value: 1\nMaximum value: 63" },
          state: { api: 'state', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "State of the monitor. The DISABLED setting disables not only the monitor being configured, but all monitors of the same type, until the parameter is set to ENABLED. If the monitor is bound to a service, the state of the monitor is not taken into account when the state of the service is determined." },
          reverse: { api: 'reverse', kind: :truthy, values: ["YES", "NO"], desc: "Mark a service as DOWN, instead of UP, when probe criteria are satisfied, and as UP instead of DOWN when probe criteria are not satisfied.\nPossible values: YES, NO\nDefault value: NO" },
          transparent: { api: 'transparent', kind: :truthy, values: ["YES", "NO"], desc: "The monitor is bound to a transparent device such as a firewall or router. The state of a transparent device depends on the responsiveness of the services behind it. If a transparent device is being monitored, a destination IP address must be specified. The probe is sent to the specified IP address by using the MAC address of the transparent device.\nPossible values: YES, NO\nDefault value: NO" },
          lrtm: { api: 'lrtm', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Calculate the least response times for bound services. If this parameter is not enabled, the appliance does not learn the response times of the bound services. Also used for LRTM load balancing.\nPossible values: ENABLED, DISABLED" },
          secure: { api: 'secure', kind: :truthy, values: ["YES", "NO"], desc: "Use a secure SSL connection when monitoring a service. Applicable only to TCP based monitors. The secure option cannot be used with a CITRIX-AG monitor, because a CITRIX-AG monitor uses a secure connection by default.\nPossible values: YES, NO\nDefault value: NO" },
          ip_tunnel: { api: 'iptunnel', kind: :truthy, values: ["YES", "NO"], desc: "Send the monitoring probe to the service through an IP tunnel. A destination IP address must be specified.\nPossible values: YES, NO\nDefault value: NO" },
          http_request: { api: 'httprequest', kind: :string, desc: "HTTP request to send to the server (for example, \"HEAD /file.html\")." },
          response_codes: { api: 'respcode', kind: :array, desc: "Response codes for which to mark the service as UP. For any other response code, the action performed depends on the monitor type. HTTP monitors and RADIUS monitors mark the service as DOWN, while HTTP-INLINE monitors perform the action indicated by the Action parameter." },
          send_string: { api: 'send', kind: :string, desc: "String to send to the service. Applicable to TCP-ECV, HTTP-ECV, and UDP-ECV monitors." },
          receive_string: { api: 'recv', kind: :string, desc: "String expected from the server for the service to be marked as UP. Applicable to TCP-ECV, HTTP-ECV, and UDP-ECV monitors." },
          custom_header: { api: 'customheaders', kind: :string, desc: "Custom header string to include in the monitoring probes." },
          query: { api: 'query', kind: :string, desc: "Domain name to resolve as part of monitoring the DNS service (for example, example.com)." },
          query_type: { api: 'querytype', kind: :string, desc: "Type of DNS record for which to send monitoring queries. Set to Address for querying A records, AAAA for querying AAAA records, and Zone for querying the SOA record.\nPossible values: Address, Zone, AAAA" },
          ip_address: { api: 'ipaddress', kind: :array, desc: "Set of IP addresses expected in the monitoring response from the DNS server, if the record type is A or AAAA. Applicable to DNS monitors." },
          script_name: { api: 'scriptname', kind: :string, desc: "Path and name of the script to execute. The script must be available on the NetScaler appliance, in the /nsconfig/monitors/ directory." },
          dispatcher_ip: { api: 'dispatcherip', kind: :string, desc: "IP address of the dispatcher to which to send the probe." },
          dispatcher_port: { api: 'dispatcherport', kind: :integer, desc: "Port number on which the dispatcher listens for the monitoring probe." },
          file_name: { api: 'filename', kind: :string, desc: "Name of a file on the FTP server. The appliance monitors the FTP service by periodically checking the existence of the file on the server. Applicable to FTP-EXTENDED monitors." },
          base_dn: { api: 'basedn', kind: :string, desc: "The base distinguished name of the LDAP service, from where the LDAP server can begin the search for the attributes in the monitoring query. Required for LDAP service monitoring." },
          bind_dn: { api: 'binddn', kind: :string, desc: "The distinguished name with which an LDAP monitor can perform the Bind operation on the LDAP server. Optional. Applicable to LDAP monitors." },
          filter: { api: 'filter', kind: :string, desc: "Filter criteria for the LDAP query. Optional." },
          attribute: { api: 'attribute', kind: :string, desc: "Attribute to evaluate when the LDAP server responds to the query. Success or failure of the monitoring probe depends on whether the attribute exists in the response. Optional." },
          validate_credentials: { api: 'validatecred', kind: :truthy, values: ["YES", "NO"], desc: "Validate the credentials of the Xen Desktop DDC server user. Applicable to monitors of type CITRIX-XD-DDC.\nPossible values: YES, NO\nDefault value: NO" },
          user_name: { api: 'username', kind: :string, desc: "User name with which to probe the RADIUS, NNTP, FTP, FTP-EXTENDED, MYSQL, MSSQL, POP3, CITRIX-AG, CITRIX-XD-DDC, CITRIX-WI-EXTENDED, CITRIX-XNC or CITRIX-XDM server." },
          password: { api: 'password', kind: :string, desc: "Password that is required for logging on to the RADIUS, NNTP, FTP, FTP-EXTENDED, MYSQL, MSSQL, POP3, CITRIX-AG, CITRIX-XD-DDC, CITRIX-WI-EXTENDED, CITRIX-XNC-ECV or CITRIX-XDM server. Used in conjunction with the user name specified for the User Name parameter." },
          group_name: { api: 'group', kind: :string, desc: "Name of a newsgroup available on the NNTP service that is to be monitored. The appliance periodically generates an NNTP query for the name of the newsgroup and evaluates the response. If the newsgroup is found on the server, the service is marked as UP. If the newsgroup does not exist or if the search fails, the service is marked as DOWN. Applicable to NNTP monitors." },
          radius_key: { api: 'radkey', kind: :string, desc: "Authentication key (shared secret text string) for RADIUS clients and servers to exchange. Applicable to monitors of type RADIUS and RADIUS_ACCOUNTING." },
          nas_id: { api: 'radnasid', kind: :string, desc: "NAS-Identifier to send in the Access-Request packet. Applicable to monitors of type RADIUS." },
          nas_ip: { api: 'radnasip', kind: :string, desc: "Network Access Server (NAS) IP address to use as the source IP address when monitoring a RADIUS server. Applicable to monitors of type RADIUS and RADIUS_ACCOUNTING." },
          account_type: { api: 'radaccounttype', kind: :integer, desc: "Account Type to be used in Account Request Packet. Applicable to monitors of type RADIUS_ACCOUNTING.\nDefault value: 1\nMaximum value: 15" },
          framed_ip: { api: 'radframedip', kind: :string, desc: "Source ip with which the packet will go out . Applicable to monitors of type RADIUS_ACCOUNTING." },
          called_station_id: { api: 'radapn', kind: :string, desc: "Called Station Id to be used in Account Request Packet. Applicable to monitors of type RADIUS_ACCOUNTING." },
          calling_station_id: { api: 'radmsisdn', kind: :string, desc: "Calling Stations Id to be used in Account Request Packet. Applicable to monitors of type RADIUS_ACCOUNTING." },
          account_session_id: { api: 'radaccountsession', kind: :string, desc: "Account Session ID to be used in Account Request Packet. Applicable to monitors of type RADIUS_ACCOUNTING." },
          origin_host: { api: 'originhost', kind: :string, desc: "Origin-Host value for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers." },
          vendor_id: { api: 'vendorid', kind: :integer, desc: "Vendor-Id value for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers." },
          origin_realm: { api: 'originrealm', kind: :string, desc: "Origin-Realm value for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers." },
          firmware_revision: { api: 'firmwarerevision', kind: :integer, desc: "Firmware-Revision value for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers." },
          product_name: { api: 'productname', kind: :string, desc: "Product-Name value for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers." },
          inband_security_id: { api: 'inbandsecurityid', kind: :string, desc: "Inband-Security-Id for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers.\nPossible values: NO_INBAND_SECURITY, TLS" },
          host_ip: { api: 'hostipaddress', kind: :string, desc: "Host-IP-Address value for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers. If Host-IP-Address is not specified, the appliance inserts the mapped IP (MIP) address or subnet IP (SNIP) address from which the CER request (the monitoring probe) is sent." },
          authentication_application_ids: { api: 'authapplicationid', kind: :array, desc: "List of Auth-Application-Id attribute value pairs (AVPs) for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers. A maximum of eight of these AVPs are supported in a monitoring CER message.\nMaximum value: 4294967295" },
          account_application_ids: { api: 'acctapplicationid', kind: :array, desc: "List of Acct-Application-Id attribute value pairs (AVPs) for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers. A maximum of eight of these AVPs are supported in a monitoring message.\nMaximum value: 4294967295" },
          supported_vendor_ids: { api: 'supportedvendorids', kind: :array, desc: "List of Supported-Vendor-Id attribute value pairs (AVPs) for the Capabilities-Exchange-Request (CER) message to use for monitoring Diameter servers. A maximum eight of these AVPs are supported in a monitoring message.\nMinimum value: 1\nMaximum value: 4294967295" },
          vendor_specific_vendor_id: { api: 'vendorspecificvendorid', kind: :integer, desc: "Vendor-Id to use in the Vendor-Specific-Application-Id grouped attribute-value pair (AVP) in the monitoring CER message. To specify Auth-Application-Id or Acct-Application-Id in Vendor-Specific-Application-Id, use vendorSpecificAuthApplicationIds or vendorSpecificAcctApplicationIds, respectively. Only one Vendor-Id is supported for all the Vendor-Specific-Application-Id AVPs in a CER monitoring message.\nMinimum value: 1" },
          script_arguments: { api: 'scriptargs', kind: :string, desc: "String of arguments for the script. The string is copied verbatim into the request." },
          sip_method: { api: 'sipmethod', kind: :string, desc: "SIP method to use for the query. Applicable only to monitors of type SIP-UDP.\nPossible values: OPTIONS, INVITE, REGISTER" },
          sip_uri: { api: 'sipuri', kind: :string, desc: "SIP URI string to send to the service (for example, sip:sip.test). Applicable only to monitors of type SIP-UDP." },
          sip_reg_uri: { api: 'sipreguri', kind: :string, desc: "SIP user to be registered. Applicable only if the monitor is of type SIP-UDP and the SIP Method parameter is set to REGISTER." },
          max_forwards: { api: 'maxforwards', kind: :integer, desc: "Maximum number of hops that the SIP request used for monitoring can traverse to reach the server. Applicable only to monitors of type SIP-UDP.\nDefault value: 1\nMaximum value: 255" },
          snmp_community: { api: 'snmpcommunity', kind: :string, desc: "Community name for SNMP monitors." },
          snmp_oid: { api: 'Snmpoid', kind: :string, desc: "SNMP OID for SNMP monitors." },
          snmp_threshold: { api: 'snmpthreshold', kind: :string, desc: "Threshold for SNMP monitors." },
          database: { api: 'database', kind: :string, desc: "Name of the database to connect to during authentication." },
          sql_query: { api: 'sqlquery', kind: :string, desc: "SQL query for a MYSQL-ECV or MSSQL-ECV monitor. Sent to the database server after the server authenticates the connection." },
          sid: { api: 'oraclesid', kind: :string, desc: "Name of the service identifier that is used to connect to the Oracle database during authentication." },
          snmp_version: { api: 'snmpversion', kind: :string, desc: "SNMP version to be used for SNMP monitors.\nPossible values: V1, V2" },
          metric_table: { api: 'metrictable', kind: :string, desc: "Metric table to which to bind metrics." },
          application_name: { api: 'application', kind: :string, desc: "Name of the application used to determine the state of the service. Applicable to monitors of type CITRIX-XML-SERVICE." },
          site_path: { api: 'sitepath', kind: :string, desc: "URL of the logon page. For monitors of type CITRIX-WEB-INTERFACE, to monitor a dynamic page under the site path, terminate the site path with a slash (/). Applicable to CITRIX-WEB-INTERFACE, CITRIX-WI-EXTENDED and CITRIX-XDM monitors." },
          rtsp_request: { api: 'rtsprequest', kind: :string, desc: "RTSP request to send to the server (for example, \"OPTIONS *\")." },
          secondary_password: { api: 'secondarypassword', kind: :string, desc: "Secondary password that users might have to provide to log on to the Access Gateway server. Applicable to CITRIX-AG monitors." },
          logon_point_name: { api: 'logonpointname', kind: :string, desc: "Name of the logon point that is configured for the Citrix Access Gateway Advanced Access Control software. Required if you want to monitor the associated login page or Logon Agent. Applicable to CITRIX-AAC-LAS and CITRIX-AAC-LOGINPAGE monitors." },
          logon_agent_service_version: { api: 'lasversion', kind: :string, desc: "Version number of the Citrix Advanced Access Control Logon Agent. Required by the CITRIX-AAC-LAS monitor." },
          domain: { api: 'domain', kind: :string, desc: "Domain in which the XenDesktop Desktop Delivery Controller (DDC) servers or Web Interface servers are present. Required by CITRIX-XD-DDC and CITRIX-WI-EXTENDED monitors for logging on to the DDC servers and Web Interface servers, respectively." },
          expression: { api: 'evalrule', kind: :string, desc: "Default syntax expression that evaluates the database server\\'s response to a MYSQL-ECV or MSSQL-ECV monitoring query. Must produce a Boolean result. The result determines the state of the server. If the expression returns TRUE, the probe succeeds.\nFor example, if you want the appliance to evaluate the error message to determine the state of the server, use the rule MYSQL.RES.ROW(10) .TEXT_ELEM(2).EQ(\"MySQL\")." },
          protocol_version: { api: 'mssqlprotocolversion', kind: :string, desc: "Version of MSSQL server that is to be monitored.\nPossible values: 70, 2000, 2000SP1, 2005, 2008, 2008R2, 2012\nDefault value: TDS_PROT_70" },
          kcd_account: { api: 'kcdaccount', kind: :string, desc: "KCD Account used by MSSQL monitor" },
          store_db: { api: 'storedb', kind: :string, desc: "Store the database list populated with the responses to monitor probes. Used in database specific load balancing if MSSQL-ECV/MYSQL-ECV monitor is configured.\nPossible values: ENABLED, DISABLED" },
          store_name: { api: 'storename', kind: :string, desc: "Store Name. For monitors of type STOREFRONT, STORENAME is an optional argument defining storefront service store name. Applicable to STOREFRONT monitors." },
          storefront_account_service: { api: 'storefrontacctservice', kind: :string, desc: "Enable/Disable probing for Account Service. Applicable only to Store Front monitors. For multi-tenancy configuration users my skip account service\nPossible values: YES, NO\nDefault value: YES" },
          check_backend_services: { api: 'storefrontcheckbackendservices', kind: :truthy, values: ["YES", "NO"], desc: "This option will enable monitoring of services running on storefront server. Storefront services are monitored by probing to a Windows service that runs on the Storefront server and exposes details of which storefront services are running." },
        },
      },
      'netscaler_service_lbmonitor_binding' => {
        nitro: 'service_lbmonitor_binding',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'service' => 'name', 'lbmonitor' => 'monitor_name' },
        doc: "Manage a binding between a service and a loadbalancing monitor.",
        title_format: '%{name}/%{monitor_name}',
        title_pattern: %r{\A(?<name>[^/]+)/(?<monitor_name>.+)\z},
        attributes: {
          weight: { api: 'weight', kind: :integer, desc: "Weight to assign to the monitor-service binding. When a monitor is UP, the weight assigned to its binding with the service determines how much the monitor contributes toward keeping the health of the service above the value configured for the Monitor Threshold parameter.\nMin = 1\nMax = 100" },
          state: { api: 'monstate', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The configured state (enable/disable) of the bound monitor." },
        },
      },
      'netscaler_servicegroup_lbmonitor_binding' => {
        nitro: 'servicegroup_lbmonitor_binding',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'servicegroup' => 'servicegroupname', 'lbmonitor' => 'monitor_name' },
        doc: "Manage a binding between a servicegroup and a loadbalancing monitor.",
        title_format: '%{servicegroupname}/%{monitor_name}',
        title_pattern: %r{\A(?<servicegroupname>[^/]+)/(?<monitor_name>.+)\z},
        attributes: {
          weight: { api: 'weight', kind: :integer, desc: "Weight to assign to the monitor-servicegroup binding. When a monitor is UP, the weight assigned to its binding with the servicegroup determines how much the monitor contributes toward keeping the health of the servicegroup above the value configured for the Monitor Threshold parameter.\nMin = 1\nMax = 100" },
          state: { api: 'monstate', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The configured state (enable/disable) of the bound monitor." },
          passive: { api: 'passive', kind: :truthy, values: [true, false], desc: "Indicates if the monitor is passive. A passive monitor does not remove servicegroup from LB decision when the threshold is breached." },
        },
      },
      'netscaler_csvserver' => {
        nitro: 'csvserver',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'lbvserver' => :default_lbvserver },
        doc: "Manage Content Switching VServer on the NetScaler appliance.",
        attributes: {
          purge_bindings: { kind: :string, ignored: "never implemented by puppetlabs-netscaler", desc: "NITRO `purgebindings`." },
          traffic_domain: { api: 'td', kind: :integer, init_only: true, desc: "Integer value that uniquely identifies the traffic domain in which you want to configure the entity. If you do not specify an ID, the entity becomes part of the default traffic domain, which has an ID of 0.\nMinimum value = 0\nMaximum value = 4094" },
          service_type: { api: 'servicetype', kind: :upcase, init_only: true, desc: "The service type of the virtual server. Valid options: HTTP, SSL, TCP, FTP, RTSP, SSL_TCP, UDP, DNS, SIP_UDP, ANY, RADIUS, RDP, MYSQL, MSSQL, DIAMETER, SSL_DIAMETER." },
          ip_address: { api: 'ipv46', kind: :string, desc: "The new IP address of the virtual server." },
          ip_pattern: { api: 'ippattern', kind: :string, desc: "The IP Pattern of the virtual server." },
          range: { api: 'range', kind: :integer, init_only: true, desc: "An IP address range.\nMinimum value: 1\nMaximum value: 254" },
          port: { api: 'port', kind: :integer, init_only: true, desc: "A port number for the virtual server.\nMinimum value: 1" },
          state: { api: 'state', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The initial state, enabled or disabled, of the virtual server." },
          state_update: { api: 'stateupdate', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "To enable the state update for a CSW vserver" },
          cacheable: { api: 'cacheable', kind: :truthy, values: ["YES", "NO"], desc: "The option to specify whether a virtual server used for content switching will route requests to the cache redirection virtual server before sending it to the configured servers." },
          redirect_url: { api: 'redirecturl', kind: :string, desc: "The redirect URL for content switching." },
          client_timeout: { api: 'clttimeout', kind: :integer, desc: "Client timeout in seconds.\nMaximum value: 31536000" },
          precedence: { api: 'precedence', kind: :upcase, desc: "The precedence on the content switching virtual server between rule-based and URL-based policies. The default precedence is set to RULE.\nIf the precedence is configured as RULE, the incoming request is applied against the content switching policies created with the -rule argument. If none of the rules match, then the URL in the request is applied against the content switching policies created with the -url option.\nFor example, this precedence can be used if certain client attributes (such as a specific type of browser) need to be served different content and all other clients can be served from the content distributed among the servers.\nIf the precedence is configured as URL, the incoming request URL is applied against the content switching policies created with the -url option. If none of the policies match, then the request is applied against the content switching policies created with the -rule option.\nAlso, this precedence can be used if some content (such as images) is the same for all clients, but other content (such as text) is different for different clients. In this case, the images will be served to all clients, but the text will be served to specific clients based on specific attributes, such as Accept-Language. Valid options: RULE, URL." },
          case_sensitive: { api: 'casesensitive', kind: :truthy, values: ["ON", "OFF"], desc: "The URL lookup case option on the content switching vserver.\nIf case sensitivity of a content switching virtual server is set to 'ON', the URLs /a/1.html and /A/1.HTML are treated differently and may have different targets (set by content switching policies).\nIf case sensitivity is set to 'OFF', the URLs /a/1.html and /A/1.HTML are treated the same, and will be switched to the same target." },
          spillover_method: { api: 'somethod', kind: :upcase, desc: "The spillover factor. When traffic on the main virtual server reaches this threshold, additional traffic is sent to the backupvserver. Valid options: CONNECTION, DYNAMICCONNECTION, BANDWIDTH, HEALTH, NONE." },
          spillover_persistence: { api: 'sopersistence', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "The state of the spillover persistence." },
          spillover_threshold: { api: 'sothreshold', kind: :integer, desc: "If the spillover method is set to CONNECTION or DYNAMICCONNECTION, this value is treated as the maximum number of connections a virtual server will handle before spillover takes place. If the spillover method is set to BANDWIDTH, this value is treated as the amount of incoming and outgoing traffic (in Kbps) a vserver will handle before spillover takes place.\nMinimum value: 1\nMaximum value: 4294967287" },
          spillover_backup_action: { api: 'sobackupaction', kind: :upcase, desc: "Action to be performed if spillover is to take effect, but no backup chain to spillover is usable or exists.\nValid options: DROP, ACCEPT, REDIRECT" },
          redirect_port_rewrite: { api: 'redirectportrewrite', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "SSL redirect port rewrite." },
          down_state_flush: { api: 'downstateflush', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Perform delayed clean up of connections on this vserver." },
          backup_virtual_server: { api: 'backupvserver', kind: :string, desc: "The backup virtual server for content switching." },
          disable_primary_on_down: { api: 'disableprimaryondown', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "When this argument is enabled, traffic will continue reaching backup vservers even after primary comes UP from DOWN state." },
          virtual_server_ip_port_insertion: { api: 'insertvserveripport', kind: :upcase, desc: "The virtual IP and port header insertion option for the vserver.\nVIPADDR - Header contains the vserver's IP address and port number without any translation.\nOFF - The virtual IP and port header insertion option is disabled.\nV6TOV4MAPPING - Header contains the mapped IPv4 address that corresponds to the IPv6 address of the vserver and the port number. An IPv6 address can be mapped to a user-specified IPv4 address using the set ns ip6 command." },
          vip_header_name: { api: 'vipheader', kind: :string, desc: "Name of virtual server IP and port header, for use with the VServer IP Port Insertion parameter.\nMinimum length = 1" },
          rtsp_natting: { api: 'rtspnat', kind: :truthy, values: ["ON", "OFF"], desc: "Use this parameter to enable natting for RTSP data connection." },
          authentication_fqdn: { api: 'authenticationhost', kind: :string, desc: "FQDN of authentication vserver" },
          authentication: { api: 'authentication', kind: :truthy, values: ["ON", "OFF"], desc: "This option toggles on or off the application of authentication of incoming users to the vserver." },
          listen_policy: { api: 'listenpolicy', kind: :string, desc: "Use this parameter to specify the listen policy for CS Vserver.\nThe string can be either an existing expression name (configured using add policy expression command) or else it can be an in-line expression with a maximum of 1499 characters." },
          listen_priority: { api: 'listenpriority', kind: :integer, desc: "Use this parameter to specify the priority for listen policy of CS Vserver.\nMaximum value: 100" },
          authentication_401: { api: 'authn401', kind: :truthy, values: ["ON", "OFF"], desc: "This option toggles on or off the HTTP 401 response based authentication." },
          authentication_virtual_server_name: { api: 'authnvsname', kind: :string, desc: "Name of authentication vserver" },
          push: { api: 'push', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Process traffic on bound Push vserver." },
          push_virtual_server_name: { api: 'pushvserver', kind: :string, desc: "The lb vserver of type PUSH/SSL_PUSH to which server pushes the updates received on the client facing non-push lb vserver." },
          push_label_expression: { api: 'pushlabel', kind: :string, desc: "Use this parameter to specify the expression to extract the label in response from server.\nThe string can be either a named expression (configured using add policy expression command) or else it can be an in-line expression with a maximum of 63 characters." },
          push_multiple_clients: { api: 'pushmulticlients', kind: :truthy, values: ["YES", "NO"], desc: "Specify if multiple web 2.0 connections from the same client can connect to this vserver and expect updates." },
          tcp_profile_name: { api: 'tcpprofilename', kind: :string, desc: "The name of the TCP profile." },
          http_profile_name: { api: 'httpprofilename', kind: :string, desc: "Name of the HTTP profile." },
          db_profile_name: { api: 'dbprofilename', kind: :string, desc: "Name of the DB profile." },
          oracle_server_version: { api: 'oracleserverversion', kind: :upcase, desc: "Oracle server version. Valid options: 10G, 11G." },
          comment: { api: 'comment', kind: :string, desc: "Comments associated with this virtual server." },
          mssql_server_version: { api: 'mssqlserverversion', kind: :upcase, desc: "The version of the MSSQL server. Valid options: 70, 2000, 2000SP1, 2005, 2008, 2008R2." },
          layer2_parameters: { api: 'l2conn', kind: :truthy, values: ["ON", "OFF"], desc: "Use L2 Parameters to identify a connection" },
          mysql_protocol_version: { api: 'mysqlprotocolversion', kind: :integer, desc: "The protocol version returned by the mysql vserver." },
          mysql_server_version: { api: 'mysqlserverversion', kind: :string, desc: "The server version string returned by the mysql vserver." },
          mysql_character_set: { api: 'mysqlcharacterset', kind: :integer, desc: "The character set returned by the mysql vserver." },
          mysql_server_capabilities: { api: 'mysqlservercapabilities', kind: :integer, desc: "The server capabilities returned by the mysql vserver." },
          appflow_logging: { api: 'appflowlog', kind: :truthy, values: ["ENABLED", "DISABLED"], desc: "Enable logging appflow flow information" },
          net_profile_name: { api: 'netprofile', kind: :string, desc: "The name of the network profile." },
          icmp_virtual_server_response: { api: 'icmpvsrresponse', kind: :upcase, desc: "Can be active or passive. Valid options: PASSIVE, ACTIVE." },
          ip_mask: { api: 'ipmask', kind: :string, desc: "The IP Mask of the virtual server IP Pattern" },
          spillover_persistence_timeout: { api: 'sopersistencetimeout', kind: :integer, desc: "The spillover persistency entry timeout.\nMinimum value: 2\nMaximum value: 1440" },
          rhi_state: { api: 'rhistate', kind: :upcase, desc: "A host route is injected according to the setting on the virtual servers * If set to PASSIVE on all the virtual servers that share the IP address, the appliance always injects the hostroute. * If set to ACTIVE on all the virtual servers that share the IP address, the appliance injects even if one virtual server is UP. * If set to ACTIVE on some virtual servers and PASSIVE on the others, the appliance, injects even if one virtual server set to ACTIVE is UP. Valid options: PASSIVE, ACTIVE" },
          authentication_profile_name: { api: 'authnprofile', kind: :string, desc: "Name of the authentication profile to be used when authentication is turned on." },
          default_lbvserver: { api: 'defaultlbvserver', kind: :string, desc: "The virtual server name to which content will be switched. This is a special case, where the binding to the lbvserver is created when the csvserver is created" },
        },
      },
      'netscaler_cspolicy' => {
        nitro: 'cspolicy',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'csaction' => :action },
        doc: "Manage basic netscaler cs policy objects.",
        attributes: {
          action: { api: 'action', kind: :string, desc: "Name of the cs action to perform if the request matches this cs policy." },
          log_action: { api: 'logaction', kind: :string, desc: "Name of the messagelog action to use for requests that match this policy." },
          domain: { kind: :string, ignored: "classic policies were removed in NetScaler 13.1, use `rule`", desc: "The domain name. The string value can range to 63 characters." },
          url: { kind: :string, ignored: "classic policies were removed in NetScaler 13.1, use `rule`", desc: "URL string that is matched with the URL of a request. Can contain a wildcard character. Specify the string value in the following format: [[prefix] [*]] [.suffix]." },
          expression: { api: 'rule', kind: :string, desc: "Expression, or name of a named expression, against which traffic is evaluated. Written in the classic or default syntax." },
        },
      },
      'netscaler_csaction' => {
        nitro: 'csaction',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'lbvserver' => :target_lbvserver },
        doc: "Manage basic netscaler content switching action objects.",
        attributes: {
          target_lbvserver: { api: 'targetlbvserver', kind: :string, desc: "Name of the load balancing virtual server to which the content is switched." },
          target_lb_expression: { api: 'targetvserverexpr', kind: :string, desc: "Information about this content switching action." },
          comments: { api: 'comment', kind: :string, desc: "Any information about the responder action." },
        },
      },
      'netscaler_csvserver_cspolicy_binding' => {
        nitro: 'csvserver_cspolicy_binding',
        # Ordering (autorequire), as puppetlabs-netscaler declared it
        autorequire: { 'csvserver' => 'name', 'cspolicy' => 'policyname', 'lbvserver' => :target_lbvserver },
        doc: "Manage a binding between a content switching vserver and a content switching policy.",
        title_format: '%{name}/%{policyname}',
        title_pattern: %r{\A(?<name>[^/]+)/(?<policyname>.+)\z},
        attributes: {
          priority: { api: 'priority', kind: :integer, desc: "The priority of the policy binding.\nMin = 1\nMax = 2147483647" },
          goto_expression: { api: 'gotopriorityexpression', kind: :string, desc: "Expression specifying the priority of the next policy which will get evaluated if the current policy rule evaluates to TRUE" },
          label_name: { api: 'labelname', kind: :string, desc: "Label of policy to invoke if the bound policy evaluates to true." },
          target_lbvserver: { api: 'targetlbvserver', kind: :string, desc: "The virtual server name to which content will be switched." },
        },
      },
      'netscaler_sslcertkey' => {
        nitro: 'sslcertkey',
        doc: "Configuration for Imported Certfile resource",
        attributes: {
